style.css:
@-moz-document domain("roblox.com") {
/* Set the fish background using the Pinterest image */
    body {
        background: url('https://i.pinimg.com/736x/e0/d5/43/e0d543c83b71e540b4b5e2ba54a1c331.jpg') no-repeat center center fixed !important;
        background-size: cover !important; /* Cover the entire page */
        color: white !important;
        position: relative;
        z-index: -1; /* Make sure the fish background is behind content */
    }

    /* Content containers, with transparency */
    .container, .navbar, .profile-header, .game-card {
        background: rgba(0, 123, 255, 0.3) !important; /* Light blue transparency */
        border-radius: 10px !important;
        border: 1px solid #00aaff !important; /* Ocean blue border */
        position: relative;
        z-index: 1; /* Ensure content is above background */
    }

    /* Buttons with ocean theme */
    .btn-primary {
        background: linear-gradient(45deg, #00c3ff, #0082ff) !important;
        border: none !important;
        color: white !important;
        text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.5);
    }

    /* Links with coral color */
    a {
        color: #ff6f61 !important;
    }

    /* Hover effect on game cards */
    .game-card:hover {
        transform: scale(1.05);
        transition: 0.3s ease-in-out;
        background: rgba(0, 255, 255, 0.3) !important;
    }

    /* Avatar background */
    .avatar-card {
        background: rgba(0, 255, 200, 0.2) !important;
        border-radius: 15px !important;
    }

    /* Footer with deep-sea vibe */
    .footer {
        background: rgba(0, 50, 100, 0.8) !important;
        color: lightblue !important;
    }
}
